from itertools import combinations

def build_grid(m, n, torus=False):
    # vertices (i,j), i in 0..m-1, j in 0..n-1
    V = [(i,j) for i in range(m) for j in range(n)]
    idx = {v:k for k,v in enumerate(V)}
    N = [[] for _ in range(len(V))]
    for (i,j) in V:
        for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i+di, j+dj
            if torus:
                ni %= m; nj %= n
                N[idx[(i,j)]].append(idx[(ni,nj)])
            else:
                if 0 <= ni < m and 0 <= nj < n:
                    N[idx[(i,j)]].append(idx[(ni,nj)])
    return V, N

def gamma_2t(m, n, torus=False):
    V, N = build_grid(m, n, torus)
    nv = len(V)
    # brute force over subsets of increasing size
    for size in range(1, nv+1):
        for S in combinations(range(nv), size):
            sset = set(S)
            ok = True
            for v in range(nv):
                cnt = sum(1 for u in N[v] if u in sset)
                if cnt < 2:
                    ok = False
                    break
            if ok:
                return size
    return nv

for n in range(2, 13):
    print(n, gamma_2t(3, n, False))
