import mpmath as mp
mp.mp.dps = 30

def Jnum(s):
    # Hadamard finite part of ∫_0^∞ x^s/((x-1)^2 (x+1)) dx
    # split: (0,1-eps),(1+eps,∞) plus counterterm 1/(x-1)^2
    f = lambda x: x**s/((x-1)**2*(x+1))
    def fp(eps):
        a = mp.quad(f, [0, 1-eps])
        b = mp.quad(f, [1+eps, mp.inf])
        # counterterm: ∫_0^∞ 1/(x-1)^2 dx in finite part sense around 1:
        # ∫_0^{1-eps} + ∫_{1+eps}^R of 1/(x-1)^2 = [ -1/(x-1)]_0^{1-eps} + [-1/(x-1)]_{1+eps}^R
        # = (1/eps + 1) + (1/eps - 1/R) -> 2/eps + 1 - 1/R ; as R->inf: 2/eps + 1
        # subtract (2/eps + 1)
        return a + b - (2/eps + 1)
    e1 = fp(mp.mpf('1e-4'))
    e2 = fp(mp.mpf('1e-5'))
    return e2  # crude; Richardson:
def Jnum2(s):
    f = lambda x: x**s/((x-1)**2*(x+1))
    def fp(eps):
        a = mp.quad(f, [0, 1-eps])
        b = mp.quad(f, [1+eps, mp.inf])
        return a + b - (2/eps + 1)
    e1 = fp(mp.mpf('1e-3')); e2 = fp(mp.mpf('1e-4')); e3 = fp(mp.mpf('1e-5'))
    # Richardson extrapolation in eps (linear in eps)
    v1 = e1 + (e1-e2)  # eps=1e-3 -> 1e-4
    v2 = e2 + (e2-e3)
    return v2 + (v2-v1)

for s in [mp.mpf('0.5'), mp.mpf('0.25'), mp.mpf('0.75')]:
    print(s, Jnum2(s))

# candidate formula
def Jform(s):
    return mp.mpf('0.5')*(mp.pi*s*mp.cos(mp.pi*s)/mp.sin(mp.pi*s)**2 - mp.pi/2*mp.cos(mp.pi*s/2)/mp.sin(mp.pi*s/2))
for s in [mp.mpf('0.5'), mp.mpf('0.25'), mp.mpf('0.75')]:
    print(s, Jform(s))
