import mpmath as mp
mp.mp.dps = 50

def integrand(x):
    if x == 0:
        return 0.0
    # ln((e^{pi x}-1)/(e^{pi x}+1)) = ln(tanh(pi x / 2))
    return mp.log(1+x**2) * mp.log(mp.tanh(mp.pi*x/2))

Psi = mp.quad(integrand, [0, mp.inf])
print("Psi =", mp.nstr(Psi, 40))
print("Psi/pi =", mp.nstr(Psi/mp.pi, 40))
"}

